const safe = (name) => { try { return $(name).all().map(i => i.json).filter(j => !j.error); } catch (e) { return []; } };
const num = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const rows = [];
for (const c of safe('Google Ads Campaigns')) {
  rows.push({ platform: 'Google Ads', campaign: c.name, spend: num(c.costMicros) / 1e6, impressions: num(c.impressions), clicks: num(c.interactions), conversions: num(c.conversions), revenue: num(c.conversionsValue) });
}
for (const r of safe('Meta Ads Insights')) {
  for (const c of (r.data || [])) {
    const conv = (c.actions || []).filter(a => a.action_type === 'purchase' || a.action_type === 'lead').reduce((s, a) => s + num(a.value), 0);
    const rev = (c.action_values || []).filter(a => a.action_type === 'purchase').reduce((s, a) => s + num(a.value), 0);
    rows.push({ platform: 'Meta Ads', campaign: c.campaign_name, spend: num(c.spend), impressions: num(c.impressions), clicks: num(c.clicks), conversions: conv, revenue: rev });
  }
}
for (const r of safe('TikTok Ads Report')) {
  for (const c of ((r.data && r.data.list) || [])) {
    const m = c.metrics || {};
    const spend = num(m.spend);
    rows.push({ platform: 'TikTok Ads', campaign: m.campaign_name || (c.dimensions || {}).campaign_id, spend, impressions: num(m.impressions), clicks: num(m.clicks), conversions: num(m.conversion), revenue: spend * num(m.complete_payment_roas) });
  }
}
const ga4 = safe('GA4 Channel Performance');
const ga4ByCampaign = {};
for (const g of ga4) {
  const k = g.campaignName || '(not set)';
  ga4ByCampaign[k] = ga4ByCampaign[k] || { sessions: 0, keyEvents: 0, revenue: 0 };
  ga4ByCampaign[k].sessions += num(g.sessions); ga4ByCampaign[k].keyEvents += num(g.keyEvents); ga4ByCampaign[k].revenue += num(g.totalRevenue);
}
for (const r of rows) {
  const g = ga4ByCampaign[r.campaign];
  r.ga4_sessions = g ? g.sessions : 0; r.ga4_conversions = g ? g.keyEvents : 0; r.ga4_revenue = g ? g.revenue : 0;
  if (!r.revenue && r.ga4_revenue) r.revenue = r.ga4_revenue;
  if (!r.conversions && r.ga4_conversions) r.conversions = r.ga4_conversions;
  r.ctr = r.impressions ? +(r.clicks / r.impressions * 100).toFixed(2) : 0;
  r.cvr = r.clicks ? +(r.conversions / r.clicks * 100).toFixed(2) : 0;
  r.cpa = r.conversions ? +(r.spend / r.conversions).toFixed(2) : null;
  r.roas = r.spend ? +(r.revenue / r.spend).toFixed(2) : null;
  r.roi_pct = r.spend ? +((r.revenue - r.spend) / r.spend * 100).toFixed(1) : null;
}
const totals = rows.reduce((t, r) => ({ spend: t.spend + r.spend, revenue: t.revenue + r.revenue, conversions: t.conversions + r.conversions }), { spend: 0, revenue: 0, conversions: 0 });
const byPlatform = {};
for (const r of rows) {
  const p = byPlatform[r.platform] = byPlatform[r.platform] || { spend: 0, revenue: 0, conversions: 0 };
  p.spend += r.spend; p.revenue += r.revenue; p.conversions += r.conversions;
}
const attribution = Object.entries(byPlatform).map(([platform, p]) => ({
  platform, spend: +p.spend.toFixed(2), revenue: +p.revenue.toFixed(2), conversions: p.conversions,
  spend_share_pct: totals.spend ? +(p.spend / totals.spend * 100).toFixed(1) : 0,
  revenue_share_pct: totals.revenue ? +(p.revenue / totals.revenue * 100).toFixed(1) : 0,
  conversion_share_pct: totals.conversions ? +(p.conversions / totals.conversions * 100).toFixed(1) : 0,
  roas: p.spend ? +(p.revenue / p.spend).toFixed(2) : null
}));
const channelMix = {};
for (const g of ga4) {
  const k = g.sourceMedium || '(direct)';
  channelMix[k] = channelMix[k] || { sessions: 0, conversions: 0, revenue: 0 };
  channelMix[k].sessions += num(g.sessions); channelMix[k].conversions += num(g.keyEvents); channelMix[k].revenue += num(g.totalRevenue);
}
const abGroups = {};
for (const r of rows) {
  const m = /AB:([^:]+):([A-Za-z0-9]+)/.exec(r.campaign || '');
  if (!m) continue;
  (abGroups[m[1]] = abGroups[m[1]] || []).push({ variant: m[2], platform: r.platform, clicks: r.clicks, conversions: r.conversions, spend: r.spend, cvr: r.cvr, cpa: r.cpa });
}
const abTests = Object.entries(abGroups).map(([test, variants]) => {
  const sorted = [...variants].sort((a, b) => (b.conversions / (b.clicks || 1)) - (a.conversions / (a.clicks || 1)));
  let z = null, significant = false;
  if (sorted.length >= 2) {
    const [a, b] = sorted; const p1 = a.conversions / (a.clicks || 1), p2 = b.conversions / (b.clicks || 1);
    const p = (a.conversions + b.conversions) / ((a.clicks + b.clicks) || 1);
    const se = Math.sqrt(p * (1 - p) * (1 / (a.clicks || 1) + 1 / (b.clicks || 1)));
    z = se ? +((p1 - p2) / se).toFixed(2) : null; significant = z !== null && Math.abs(z) >= 1.96;
  }
  return { test, variants, leader: sorted[0] ? sorted[0].variant : null, z_score: z, significant_95: significant, min_clicks_reached: variants.every(v => v.clicks >= 300) };
});
return [{ json: {
  period: 'last 7 days', generated_at: new Date().toISOString(),
  totals: { spend: +totals.spend.toFixed(2), revenue: +totals.revenue.toFixed(2), conversions: totals.conversions, roas: totals.spend ? +(totals.revenue / totals.spend).toFixed(2) : null, roi_pct: totals.spend ? +((totals.revenue - totals.spend) / totals.spend * 100).toFixed(1) : null },
  attribution, channel_mix_ga4: channelMix, campaigns: rows.sort((a, b) => b.spend - a.spend), ab_tests: abTests
} }];

const base = $('Compute KPIs, Attribution & A/B Stats').first().json;
const since = $now.minus({ days: 7 });
const rows = $input.all().map(i => i.json).filter(r => r && r.segment && (!r.createdAt || DateTime.fromISO(String(r.createdAt)) >= since));
const count = (key) => rows.reduce((m, r) => { const k = r[key] || '(none)'; m[k] = (m[k] || 0) + 1; return m; }, {});
const hot = rows.filter(r => r.segment === 'hot').length;
const spend = (base.totals && base.totals.spend) || 0;
const crm_leads = {
  source: 'L4 Lead Nurturing Agent (leads table)',
  total_leads: rows.length,
  hot_leads: hot,
  avg_score: rows.length ? +(rows.reduce((s, r) => s + (Number(r.score) || 0), 0) / rows.length).toFixed(1) : null,
  by_segment: count('segment'),
  by_source: count('source'),
  by_campaign: count('campaign'),
  by_status: count('status'),
  true_cost_per_lead: rows.length && spend ? +(spend / rows.length).toFixed(2) : null,
  cost_per_hot_lead: hot && spend ? +(spend / hot).toFixed(2) : null
};
return [{ json: { ...base, crm_leads } }];
